<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Payment</h2></div><div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Amount</span><input class="sl-in mono" name="amount" id="rp-amount" inputmode="decimal" value="<?= number_format($d['selectedTotal'], 2, '.', '') ?>" required></label><label class="sl-field"><span class="sl-lab">Currency</span><label class="sl-sel native"><select name="currency" id="rp-currency" aria-label="Currency"><option value="<?= h($d['currency']) ?>"><?= h($d['currency']) ?></option><?php if ($d['rate'] > 0 && $d['currency'] !== 'GHS'): ?><option value="GHS">GHS (÷ <?= number_format($d['rate'], 2) ?>)</option><?php endif; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></label></label></div><div class="sl-field"><span class="sl-lab">Method</span><div class="sl-seg boxed" data-sl-filter-seg style="flex-wrap:wrap;height:auto;max-width:100%"><?php foreach ($d['methods'] as $k => $m): ?><button type="button" class="<?= $k === 0 ? 'on' : '' ?>" data-method="<?= (int) $m->id ?>" onclick="document.getElementById('rp-method').value=this.dataset.method"><?= h($m->label) ?></button><?php endforeach; ?></div><input type="hidden" name="method" id="rp-method" value="<?= $d['methods'] ? (int) $d['methods'][0]->id : 0 ?>"></div><div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Reference</span><input class="sl-in mono" name="reference" placeholder="Receipt, MoMo or transfer reference"></label><label class="sl-field"><span class="sl-lab">Date</span><input class="sl-in mono" type="date" name="paid_at" value="<?= h($d['today']) ?>"></label></div><label class="sl-field"><span class="sl-lab">Note</span><input class="sl-in" name="note" maxlength="190" placeholder="Optional"></label></section></div>
