<script>
(function(){var f=document.getElementById('rp-form');if(!f)return;var sym=<?= json_encode($core->for_symbol ?? '$') ?>;function fmt(n){return sym+n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function recalc(){var t=0,n=0;f.querySelectorAll('input[name="orders[]"]').forEach(function(c){c.closest('.np-opt').classList.toggle('on',c.checked);c.closest('.np-opt').querySelector('.sl-chk').classList.toggle('on',c.checked);if(c.checked){t+=parseFloat(c.dataset.amt)||0;n++;}});
var paid=parseFloat(document.getElementById('rp-amount').value)||0;if(document.getElementById('rp-currency').value==='GHS'&&<?= (float) $d['rate'] ?>>0)paid=paid/<?= (float) $d['rate'] ?>;
document.getElementById('rp-n').textContent=n;document.getElementById('rp-total').textContent=fmt(t);document.getElementById('rp-paid').textContent=fmt(paid);document.getElementById('rp-left').textContent=fmt(Math.max(0,t-paid));}
f.addEventListener('change',function(e){if(e.target.name==='orders[]'){var t=0;f.querySelectorAll('input[name="orders[]"]:checked').forEach(function(c){t+=parseFloat(c.dataset.amt)||0;});document.getElementById('rp-amount').value=t.toFixed(2);}recalc();});f.addEventListener('input',recalc);recalc();})();
</script>
